    return Err(StaleRow(id));   // someone else committed first
}

let mut current = version.load(Ordering::Acquire);
loop {
    let next = compute(current);
    match version.compare_exchange_weak(
        current, next, Ordering::AcqRel, Ordering::Acquire) {
        Ok(_) => break,
        Err(actual) => current = actual,   // conflict: re-read, recompute
    }
}

